    {"claim": "Frontier AI should be gated by compute-threshold licensing as a precautionary floor — not because catastrophe is certain, but because some frontier capabilities cannot be recalled once released.", "targets": [], "relationship": ""},
    {"claim": "The Boeing 737 MAX killed 346 people because the FAA let Boeing certify its own flight-control software.", "targets": [], "relationship": ""},
    {"claim": "Compute is a proxy, not a risk measure, so the threshold cannot be a frozen statute — it must be a recalibrating floor, indexed to capability and revised on a schedule.", "targets": [], "relationship": ""},
    {"claim": "When the Price-Anderson Act forced nuclear operators to carry mandatory insurance, it did not slow the industry — it priced safety into every operating decision for sixty years.", "targets": [], "relationship": ""},
    {"claim": "Capability concentration already exists; a handful of well-capitalized labs already command the frontier opaquely, so gating plus transparency puts an inspector inside the moat rather than digging it.", "targets": [], "relationship": ""}
  ]
}

